INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63204895', 63204895, 'analyze_legacy', 'Kab. Sinjai', 'kabkota', 'DINAS SOSIAL', 'Belanja Iuaran Jaminan Kecelakaan Kerja Bagi Pekerja Rentan pada Sub Kegiatan Fasilitasi Bantuan  Sosial Kesejahtraan Keluarga', 'Jasa Lainnya', 'Dikecualikan', 'Sulawesi Selatan, Sinjai (Kab.)', 153360000, 'January 2026', 'APBD', 1, 1, '1278 0rang x 12 bulan', 'Belanja Iuaran Jaminan Kecelakaan Kerja Bagi Kerja Rentan', 'Iuran Jaminan Kecelakaan Kerja Bagi Pekerja Rentann Peserta Bukan Penerima Upah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 740729);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62668067', 62668067, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Belanja Jasa Lainnya Pengelolaan Informasi Kekayaan Intelektual Media Monitoring pada Direktorat Jenderal Kekayaan Intelektual Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 140000000, 'December 2025', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penyedia menyiapkan laporan terkait sentimen masyarakat terhadap institusi Direktorat Jenderal Kekayaan Intelektual melalui pengamatan terhadap pemberitaan berbagai media online dan media cetak, serta perbincangan/posting warganet dalam media sosial. Selain itu, analisis juga dibutuhkan untuk memantau sebaran sosialisasi seluruh isu-isu kekayaan intelektual.', 'Ruang Lingkup Pekerjaan Monitoring Media meliputi: 1. Mendapatkan hasil monitoring pemberitaan dengan topik yang telah ditentukan melalui Laporan Harian, Mingguan dan Bulanan. Monitoring pemberitaan yang diharapkan terdiri dari: a. Menyampaikan kompilasi berita sesuai dengan sumber isu, media, tanggal pemberitaan, judul berita isi berita, nama reporter dan nama narasumber; b. Mapping tonasi dan tendensi media terhadap suatu isu/topik; c. Kuantitas pemberitaan di media terkait key messages yang disampaikan oleh Direktorat Jenderal Kekayaan Intelektual maupun isu/topik lainnya yang terkait dengan Direktorat Jenderal Kekayaan Intelektual . 2. Mendapatkan analisis pemberitaan secara komprehensif dengan melakukan cross check di lapangan dan memberikan laporan investigasi terkait dengan pemberitaan dan isu-isu khusus di media massa online, pembicaraan warganet dalam media sosial, serta opini dari stakeholders yang berkaitan dengan pelaksanaan program dan kebijakan Direktorat Jenderal Kekayaan Intelektual. 3. Memperoleh alert info berita dengan tendensi negatif yang berkaitan dengan Direktorat Jenderal Kekayaan Intelektual. 4. Menyediakan sistem yang dapat mengumpulkan data dan informasi media (open-source intelligence/OSINT): a. Memperoleh informasi terkini dengan cepat, akurat, lengkap dan real time.; Sistem bekerja secara otomatis dan terus-menerus selama 24 jam sehari; b. Sumber informasi dari media nasional dan internasional; c. Sumber informasi dapat diperoleh dalam jumlah yang tidak terbatas. 5. Melakukan analisis informasi pemantauan media untuk dukungan pengambilan keputusan : a. Mendapatkan tren atau sentiment dari laporan, berita dan opini media terkait secara real time dan akurat; b. Mengetahui dengan lebih cepat tren persoalan yang sedang terjadi; c. Bisa membaca kronologi (timeline) dari setiap peristiwa; d. Mendapatkan isu yang ada di tiap permasalahan; e. Mengetahui tokoh yang berperan dalam kasus; f. Mengetahui jurnalis/reporter yang memberitakan isu kekayaan intelektual g. Menganalisis setiap media untuk mengetahui keberpihakan media; h. Melihat peta untuk mengetahui penyebaran isu; i. Menganalisis sentimen untuk mengetahui tendensi; j. Ontology untuk mengetahui jaringan keterkaitan antar orang, organisasi, dan permasalahan. k. Menganalisis PR value dari berita yang dirilis DJKI 6. Memberi informasi strategis ke jajaran pimpinan Direktorat Jenderal Kekayaan Intelektual, menyangkut hal yang harus dilakukan lewat media, pendekatan media, kebijakan melalui counter issue, klarifikasi, penegasan, kebijakan. 7. Analisis dan monitoring media dan evaluasi Kinerja Direktorat Jenderal Kekayaan Intelektual dan seluruh jajarannya secara cepat dan akurat dengan memperhatikan sisi persepsi publik. 8. Sistem dapat diakses dengan menggunakan berbagai macam device seperti notebook, tablet, smartphone dari berbagai tempat, kapan saja, di manapun juga, dengan rincian sebagai berikut: - Akses pengguna: 5 user - Media online dan sosial media : 10 topics 9. Mengadakan pelatihan bagi petugas dalam menggunakan sistem/aplikasi media monitoring minimal 2 kali pelatihan. 10. Laporan kegiatan disampaikan setiap hari dan setiap bulan (laporan monitoring media online, laporan monitoring media cetak, laporan monitoring media sosial) yang dikirimkan melalui email kepada Tim Kerja Hubungan Masyarakat dan Koordinasi Pelayanan Informasi Publik dengan rincian cakupan sebagai berikut : - Laporan Harian : 25-30 laporan x 9 bulan = 225-270 laporan - Laporan Mingguan : 4-5 laporan x 9 bulan = 36-45 laporan - Laporan Bulanan : 1 laporan x 9 bulan = 9 laporan - Laporan Insidental : 1 laporan x 9 bulan = 9 laporan maksimal Media Cetak: Laporan mencakup: - Sumber isu - Judul berita, isi berita dan nama narasumber - Tendensi berita media cetak - Persebaran media cetak - Nama jurnalis/reporter - Tren pemberitaan media cetak - Isu utama media cetak - Influencer media cetak - Peta persebaran media cetak - Media share (media cetak) - Rekomendasi Media Online: - Sumber isu - Judul berita, isi berita dan nama narasumber - Tendensi berita - Persebaran media online - Nama jurnalis/reporter - Tren pemberitaan media online - Ekspos unit Ditjen Kekayaan Intelektual - Isu utama media online - Alerting isu kekayaan intelektual - Influencers - Top persons - Peta persebaran berita - Perbandingan topik strategis Ditjen Kekayaan Intelektual - Rekomendasi Media Sosial - Ekspos dan sentimen - Isu utama - Emosi warganet - Akun Twitter, Youtube, Instagram, Facebook, dan Tiktok - Jejaring akun Twitter, Youtube, Instagram, Facebook, dan Tiktok - Demografi - Sebaran data - Isu utama - Respons publik (positif, netral dan negatif) 11. Menyampaikan laporan khusus terkait isu-isu tertentu yang dirasa penting untuk dilaporkan secara terpisah dan sifatnya harus segera ditangani, sekurang- kurangnya sebanyak 9 (sembilan) laporan khusus dalam satu periode pekerjaan. Laporan khusus tersebut dilaporkan selambat-lambatnya 24 jam setelah diminta dan diserahkan kepada Ketua Tim Kerja Hubungan Masyarakat dan Koordinasi Pelayanan Informasi Publik sebanyak 9 (sembilan) eksemplar. 12. Mengadakan rapat khusus sewaktu-waktu jika diminta oleh user terkait isu-isu yang sifatnya penting, cepat menyebar, dan berpotensi untuk memberikan citra negatif terhadap Direktorat Jenderal Kekayaan Intelektual 13. Mengadakan rapat khusus sewaktu-waktu jika diminta oleh user terkait isu-isu yang sifatnya penting, cepat menyebar, dan berpotensi untuk memberikan citra negatif terhadap Direktorat Jenderal Kekayaan Intelektual.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 740730);
