INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63183403', 63183403, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS KESEHATAN', 'Belanja Pengadaan Rapid HIV dan Reagen Sifilis Duo untuk Skrining Bumil 1246 Box (31.150 Tes)', 'Barang', 'E-Purchasing', 'Banten, Tangerang (Kota)', 533474900, 'January 2026', 'APBD', 1, 1, '1246 Box', 'Belanja Pengadaan Rapid HIV dan Reagen Sifilis Duo untuk Skrining Bumil 1246 Box x 25 tes (31.150 Tes)', 'Spesifikasi Umum: 1. Telah teregistrasi dan mempunyai izin edar dari Kementerian Kesehatan RI. 2. Tersedia petunjuk penggunaan dalam bahasa Indonesia disertai ilustrasi bergambar. 3. Rentang minimal stabilitas reagen pada suhu 2-30°C. 4. Kedaluwarsa minimal 18 bulan pada saat barang diterima panitia. 5. Suhu reagen dipastikan dalam rentang stabilitas reagen yang ditentukan oleh pabrikan, sejak pengiriman dari pabrik hingga diterima di tempat tujuan pengiriman, di buktikan dengan data logger. 6. Spesifikasi Khusus Rapid Tes HIV a. Hasil akurasi berdasarkan evaluasi Laboratorium Rujukan yang ditentukan yaitu sensitivitas ≥ 99% b. Mudah dikerjakan, hasil mudah dibaca dan cepat, kurang dari 30 menit. c. Dapat mengidentifikasi antibodi HIV 1 dan HIV 2. d. Bisa digunakan untuk tiga (3) jenis bahan pemeriksaan yaitu darah lengkap (whole blood), serum dan plasma sesuai dengan petunjuk dari reagensia yang dipakai. 7. Spesifikasi khusus Rapid Tes Sifilis : a. Rapid diagnostik tes Sifilis merupakan tes yang mendeteksi antibodi yang bersfiat spesifik terhadap treponema. b. Sensitivitas ≥85%, spesifisitas ≥ 93%. c. Setiap tes dikemas individual. 8. Tersedia dropper per tes untuk sampel pemeriksaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 740893);
